using CampusPlacementManagement.Data;
using CampusPlacementManagement.DTOs.Jobs;
using CampusPlacementManagement.Models;
using CampusPlacementManagement.Models.Enums;
using CampusPlacementManagement.Repositories.Interfaces;
using CampusPlacementManagement.Services.Interfaces;
using Microsoft.EntityFrameworkCore;
namespace CampusPlacementManagement.Services;
public class JobService:IJobService
{
 private readonly IJobRepository _repo;private readonly ApplicationDbContext _db;
 public JobService(IJobRepository repo,ApplicationDbContext db){_repo=repo;_db=db;}
 private async Task<CompanyHR> GetHr(string userId)=>await _db.CompanyHRs.Include(x=>x.Company).Include(x=>x.User).FirstOrDefaultAsync(x=>x.UserId==userId)??throw new UnauthorizedAccessException("Company HR profile not found.");
 private static void Map(Job j,CreateJobDto d){j.JobTitle=d.JobTitle;j.JobDescription=d.JobDescription;j.JobType=d.JobType;j.Location=d.Location;j.SalaryPackage=d.SalaryPackage;j.MinimumCGPA=d.MinimumCGPA;j.MaximumBacklogs=d.MaximumBacklogs;j.ApplicationDeadline=d.ApplicationDeadline;j.IsOpenToAllColleges=d.IsOpenToAllColleges;}
 public async Task<Job> CreateAsync(CreateJobDto dto,string userId){var hr=await GetHr(userId);if(hr.Status!=AccountStatus.Approved||hr.Company.Status!=CompanyStatus.Approved)throw new UnauthorizedAccessException("Company HR or company is not approved.");var j=new Job{CompanyId=hr.CompanyId,CreatedByHRId=hr.CompanyHRId,Status=JobStatus.Draft};Map(j,dto);foreach(var r in dto.EligibilityRules)j.EligibilityCriteria.Add(new EligibilityCriteria{MinimumCGPA=r.MinimumCGPA,MaximumBacklogs=r.MaximumBacklogs,Department=r.Department,GraduationYear=r.GraduationYear});await _repo.AddAsync(j);await _repo.SaveChangesAsync();return j;}
 public async Task<List<Job>> GetVisibleAsync(string userId){var user=await _db.Users.Include(x=>x.Student).FirstOrDefaultAsync(x=>x.Id==userId);var college=user?.Student?.CollegeId;return await _repo.GetAllVisibleAsync(college);}
 public async Task<Job> GetByIdAsync(int id,string userId){var j=await _repo.GetByIdAsync(id)??throw new KeyNotFoundException("Job not found.");var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==userId);var student=await _db.Students.FirstOrDefaultAsync(x=>x.UserId==userId);if(j.Status!=JobStatus.Published&&hr?.CompanyHRId!=j.CreatedByHRId)throw new UnauthorizedAccessException("Job is not published.");if(student!=null&&student.CollegeId>0&&!j.IsOpenToAllColleges&&!j.TargetColleges.Any(x=>x.CollegeId==student.CollegeId))throw new UnauthorizedAccessException("Job is not targeted to your college.");return j;}
 public async Task UpdateAsync(int id,UpdateJobDto dto,string userId){var j=await _repo.GetOwnedByHrAsync(id,(await GetHr(userId)).CompanyHRId)??throw new UnauthorizedAccessException("Job ownership check failed.");if(j.Status!=JobStatus.Draft)throw new InvalidOperationException("Only draft jobs can be edited.");Map(j,dto);j.EligibilityCriteria.Clear();foreach(var r in dto.EligibilityRules)j.EligibilityCriteria.Add(new EligibilityCriteria{JobId=j.JobId,MinimumCGPA=r.MinimumCGPA,MaximumBacklogs=r.MaximumBacklogs,Department=r.Department,GraduationYear=r.GraduationYear});_repo.Update(j);await _repo.SaveChangesAsync();}
 public async Task PublishAsync(int id,string userId){var hr=await GetHr(userId);var j=await _repo.GetOwnedByHrAsync(id,hr.CompanyHRId)??throw new UnauthorizedAccessException();if(hr.Status!=AccountStatus.Approved||hr.Company.Status!=CompanyStatus.Approved)throw new UnauthorizedAccessException("Company must be approved.");if(j.ApplicationDeadline<=DateTime.UtcNow)throw new InvalidOperationException("Application deadline must be in the future.");j.Status=JobStatus.Published;_repo.Update(j);await _repo.SaveChangesAsync();}
 public async Task CloseAsync(int id,string userId){var hr=await GetHr(userId);var j=await _repo.GetOwnedByHrAsync(id,hr.CompanyHRId)??throw new UnauthorizedAccessException();j.Status=JobStatus.Closed;_repo.Update(j);await _repo.SaveChangesAsync();}
 public async Task DeleteAsync(int id,string userId){var hr=await GetHr(userId);var j=await _repo.GetOwnedByHrAsync(id,hr.CompanyHRId)??throw new UnauthorizedAccessException();if(j.Status!=JobStatus.Draft)throw new InvalidOperationException("Only draft jobs can be deleted.");_repo.Remove(j);await _repo.SaveChangesAsync();}
 public async Task AddTargetCollegeAsync(int jobId,int collegeId,string userId){var hr=await GetHr(userId);var j=await _repo.GetOwnedByHrAsync(jobId,hr.CompanyHRId)??throw new UnauthorizedAccessException();if(j.Status!=JobStatus.Draft)throw new InvalidOperationException("Targeting can be changed only for draft jobs.");if(!await _db.Colleges.AnyAsync(x=>x.CollegeId==collegeId&&x.Status==CollegeStatus.Approved))throw new InvalidOperationException("College is not approved.");if(!await _db.JobTargetColleges.AnyAsync(x=>x.JobId==jobId&&x.CollegeId==collegeId)){await _db.JobTargetColleges.AddAsync(new JobTargetCollege{JobId=jobId,CollegeId=collegeId});await _db.SaveChangesAsync();}}
 public async Task<List<JobTargetCollege>> GetTargetCollegesAsync(int jobId,string userId){var hr=await GetHr(userId);if(!await _db.Jobs.AnyAsync(x=>x.JobId==jobId&&x.CreatedByHRId==hr.CompanyHRId))throw new UnauthorizedAccessException();return await _db.JobTargetColleges.Include(x=>x.College).Where(x=>x.JobId==jobId).AsNoTracking().ToListAsync();}
 public async Task RemoveTargetCollegeAsync(int jobId,int collegeId,string userId){var hr=await GetHr(userId);if(!await _db.Jobs.AnyAsync(x=>x.JobId==jobId&&x.CreatedByHRId==hr.CompanyHRId))throw new UnauthorizedAccessException();var t=await _db.JobTargetColleges.FirstOrDefaultAsync(x=>x.JobId==jobId&&x.CollegeId==collegeId);if(t!=null){_db.JobTargetColleges.Remove(t);await _db.SaveChangesAsync();}}
}
